import React, { useEffect, useMemo, useState } from "react";
import DashboardLayout from "../components/DashboardLayout";
import SearchBar from "../components/SearchBar";
import Table from "../components/Table";
import api from "../services/api";

const Students = () => {
  const [students, setStudents] = useState([]);
  const [teachers, setTeachers] = useState([]);
  const [search, setSearch] = useState("");
  const [debouncedSearch, setDebouncedSearch] = useState("");
  const [form, setForm] = useState({ name: "", roll_number: "", class: "", parent_email: "", teacher_id: "" });

  useEffect(() => {
    const timer = setTimeout(() => setDebouncedSearch(search), 300);
    return () => clearTimeout(timer);
  }, [search]);

  useEffect(() => {
    const fetchData = async () => {
      const [studentRes, teacherRes] = await Promise.all([
        api.get(`/admin/students?search=${encodeURIComponent(debouncedSearch)}`),
        api.get("/admin/teachers"),
      ]);
      setStudents(studentRes.data.students);
      setTeachers(teacherRes.data.teachers);
    };
    fetchData();
  }, [debouncedSearch]);

  const onChange = (event) => {
    setForm((prev) => ({ ...prev, [event.target.name]: event.target.value }));
  };

  const addStudent = async (event) => {
    event.preventDefault();
    if (!form.name || !form.roll_number || !form.class || !form.parent_email) {
      return;
    }
    await api.post("/admin/add-student", {
      ...form,
      teacher_id: form.teacher_id || null,
    });
    setForm({ name: "", roll_number: "", class: "", parent_email: "", teacher_id: "" });
    const refreshed = await api.get(`/admin/students?search=${encodeURIComponent(debouncedSearch)}`);
    setStudents(refreshed.data.students);
  };

  const rows = useMemo(
    () =>
      students.map((student) => [
        student.name,
        student.roll_number,
        student.class,
        student.parent_email,
        student.teacher?.name || "-",
      ]),
    [students]
  );

  return (
    <DashboardLayout title="Students">
      <div className="panel">
        <SearchBar value={search} onChange={setSearch} placeholder="Search..." />
      </div>
      <div className="panel">
        <h3>Add Student</h3>
        <form className="grid-form" onSubmit={addStudent}>
          <input name="name" value={form.name} onChange={onChange} placeholder="Student Name" />
          <input name="roll_number" value={form.roll_number} onChange={onChange} placeholder="Roll Number" />
          <input name="class" value={form.class} onChange={onChange} placeholder="Class" />
          <input name="parent_email" value={form.parent_email} onChange={onChange} placeholder="Parent Email" type="email" />
          <select name="teacher_id" value={form.teacher_id} onChange={onChange}>
            <option value="">Assign Teacher (optional)</option>
            {teachers.map((teacher) => (
              <option key={teacher.id} value={teacher.id}>
                {teacher.name}
              </option>
            ))}
          </select>
          <button type="submit">Add Student</button>
        </form>
      </div>
      <Table headers={["Name", "Roll", "Class", "Parent Email", "Teacher"]} rows={rows} />
    </DashboardLayout>
  );
};

export default Students;
